;	$Id: msx_gfx.asm,v 1.9 2017-01-02 23:19:03 aralbrec Exp $
;
;	MSX specific routines
;	GFX - a small graphics library
;	Copyright (C) 2004 <NAME>
;
;	extern bool __FASTCALL__ msx_get_trigger(unsigned char id);
;
;	This routine is used to get the state of joystick button (trigger) number \a id.
;	\return true if the button is pressed, false otherwise.
;
;	\note This routine relies on the \c msx_get_trigger function to get the actual state.
;
;	\author <NAME>
;
;	\see msx_get_trigger
;
;	\warning This routine is not thread-safe.
;
;	\bug There is a known issue where the routine may return incorrect results if the joystick is not properly connected.
;
;	\example
;	\code
;	if (msx_get_trigger(1)) {
;		// handle button press

;
; First, we normalize x and compute exp(x) - 1.
;
; Normalize x:
;
;   AC' = x
;   BC' = 1
;
;   AC' = AC' / BC'
;
; Compute exp(x):
;
;   call am48_exp
;
; Subtract 1:
;
;   AC' = exp(x)
;   BC' = 1
;
;   call am48_dsub
;
; Handle overflow:
;
;   if AC' >= 1.0
;
;       set carry
;       set errno
;       AC' = +inf
;
;   else
;
;       carry reset
;       AC' = exp(x) - 1
;
; Return:
;
;   call am48_dpopret

   ldh a, [h_fp_exponent]
   cp 0
   jr z, no_normalize
   ldh b, [h_fp_exponent]
   ldh c, [h_fp_exponent + 1]

